<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Canvas Billiards</title>
<style>
  :root {
    color-scheme: dark;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 15%, #263746 0, #111922 45%, #090d12 100%);
    color: #f5f7f8;
  }

  .game {
    width: min(96vw, 1040px);
    padding: 18px;
  }

  h1 {
    margin: 0 0 8px;
    text-align: center;
    font-size: clamp(1.5rem, 4vw, 2.35rem);
    letter-spacing: 0.04em;
  }

  .instructions {
    margin: 0 auto 14px;
    max-width: 820px;
    text-align: center;
    line-height: 1.45;
    color: #d7e4e8;
  }

  .instructions strong { color: #fff4a8; }

  .table-shell {
    padding: 22px;
    border-radius: 24px;
    background: linear-gradient(145deg, #9a5727, #4d260f 45%, #7b421d);
    box-shadow:
      0 18px 45px #000a,
      inset 0 2px 2px #e8a86688,
      inset 0 -5px 8px #1a0808aa;
  }

  canvas {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 10px;
    cursor: crosshair;
    touch-action: none;
    background: #087553;
    box-shadow: inset 0 0 40px #001b16;
  }

  .controls {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 12px;
    margin-top: 15px;
  }

  button {
    appearance: none;
    border: 1px solid #ffcf75;
    border-radius: 999px;
    padding: 10px 19px;
    color: #271406;
    background: linear-gradient(#ffe2a1, #d99839);
    font: inherit;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 4px 12px #0008;
  }

  button:hover { filter: brightness(1.08); }
  button:active { transform: translateY(1px); }

  #status {
    min-width: 220px;
    color: #d5e8e4;
    text-align: center;
    font-variant-numeric: tabular-nums;
  }

  .hint {
    margin-top: 9px;
    text-align: center;
    color: #9eb7bd;
    font-size: 0.9rem;
  }
</style>
</head>
<body>
<main class="game">
  <h1>Canvas Billiards</h1>
  <p class="instructions">
    Wait for the balls to stop, then <strong>press the white cue ball, drag backward,
    and release</strong>. A longer drag makes a harder shot. Pot balls in the six pockets.
  </p>

  <div class="table-shell">
    <canvas id="table" width="900" height="480" aria-label="Playable billiards table"></canvas>
  </div>

  <div class="controls">
    <button id="resetButton" type="button">Reset / Rack</button>
    <span id="status">Drag the cue ball to shoot</span>
  </div>
  <div class="hint">The dashed line shows the shot direction and the colored bar shows power.</div>
</main>

<script>
(() => {
  "use strict";

  const W = 900;
  const H = 480;
  const R = 12;
  const POCKET_RADIUS = R * 1.82;
  const FRICTION = 18; // pixels per second squared
  const MAX_SHOT_SPEED = 1500;
  const canvas = document.getElementById("table");
  const ctx = canvas.getContext("2d");
  const status = document.getElementById("status");
  const resetButton = document.getElementById("resetButton");

  const pockets = [
    { x: 0, y: 0 },
    { x: W / 2, y: 0 },
    { x: W, y: 0 },
    { x: 0, y: H },
    { x: W / 2, y: H },
    { x: W, y: H }
  ];

  const ballColors = [
    "#f4d03f", "#2471db", "#d83232", "#7d3c98",
    "#e67e22", "#1d8c62", "#7f1d1d", "#151515",
    "#f4d03f", "#2471db", "#d83232", "#7d3c98",
    "#e67e22", "#1d8c62", "#7f1d1d"
  ];

  let balls = [];
  let running = true;
  let animationId = 0;
  let lastTime = 0;
  let aiming = false;
  let aimPoint = { x: 0, y: 0 };

  function finiteNumber(value, fallback = 0) {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function defaultRack() {
    const rack = [{
      x: W * 0.27,
      y: H / 2,
      vx: 0,
      vy: 0,
      cue: true
    }];

    const spacing = R * 2 + 1;
    const apexX = W * 0.68;

    for (let row = 0; row < 5; row++) {
      for (let slot = 0; slot <= row; slot++) {
        rack.push({
          x: apexX + row * spacing * 0.88,
          y: H / 2 + (slot - row / 2) * spacing,
          vx: 0,
          vy: 0,
          cue: false
        });
      }
    }
    return rack;
  }

  function reset(inputBalls) {
    const source = Array.isArray(inputBalls) ? inputBalls : [];
    balls = source.map((b) => ({
      x: finiteNumber(b && b.x),
      y: finiteNumber(b && b.y),
      vx: finiteNumber(b && b.vx),
      vy: finiteNumber(b && b.vy),
      potted: false,
      cue: !!(b && b.cue)
    }));
    aiming = false;
    lastTime = 0;
    draw();
  }

  function state() {
    return balls.map((b) => ({
      x: b.x,
      y: b.y,
      vx: b.vx,
      vy: b.vy,
      potted: b.potted,
      cue: b.cue
    }));
  }

  function cueBall() {
    return balls.find((b) => b.cue && !b.potted) || null;
  }

  function shoot(vx, vy) {
    const cue = cueBall();
    if (!cue) return;
    cue.vx = finiteNumber(vx);
    cue.vy = finiteNumber(vy);
    aiming = false;
    draw();
  }

  function isInPocket(ball) {
    for (const p of pockets) {
      const dx = ball.x - p.x;
      const dy = ball.y - p.y;
      if (dx * dx + dy * dy <= POCKET_RADIUS * POCKET_RADIUS) {
        return true;
      }
    }
    return false;
  }

  function potBall(ball) {
    ball.potted = true;
    ball.vx = 0;
    ball.vy = 0;
  }

  function handleCushions(ball) {
    while (ball.x < R || ball.x > W - R) {
      if (ball.x < R) {
        ball.x = 2 * R - ball.x;
        ball.vx = Math.abs(ball.vx);
      } else {
        ball.x = 2 * (W - R) - ball.x;
        ball.vx = -Math.abs(ball.vx);
      }
    }

    while (ball.y < R || ball.y > H - R) {
      if (ball.y < R) {
        ball.y = 2 * R - ball.y;
        ball.vy = Math.abs(ball.vy);
      } else {
        ball.y = 2 * (H - R) - ball.y;
        ball.vy = -Math.abs(ball.vy);
      }
    }
  }

  function resolveBallCollisions() {
    const diameter = R * 2;
    const diameterSq = diameter * diameter;

    for (let i = 0; i < balls.length; i++) {
      const a = balls[i];
      if (a.potted) continue;

      for (let j = i + 1; j < balls.length; j++) {
        const b = balls[j];
        if (b.potted) continue;

        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let distSq = dx * dx + dy * dy;

        if (distSq >= diameterSq) continue;

        let dist;
        let nx;
        let ny;

        if (distSq < 1e-12) {
          dist = 0;
          nx = ((i + j) & 1) ? 1 : 0;
          ny = ((i + j) & 1) ? 0 : 1;
        } else {
          dist = Math.sqrt(distSq);
          nx = dx / dist;
          ny = dy / dist;
        }

        const overlap = diameter - dist;
        const correction = overlap * 0.5 + 1e-7;
        a.x -= nx * correction;
        a.y -= ny * correction;
        b.x += nx * correction;
        b.y += ny * correction;

        const relativeNormalVelocity =
          (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;

        if (relativeNormalVelocity < 0) {
          // Equal masses and coefficient of restitution 1:
          // exchange the normal components while preserving tangential motion.
          const impulse = -relativeNormalVelocity;
          a.vx -= impulse * nx;
          a.vy -= impulse * ny;
          b.vx += impulse * nx;
          b.vy += impulse * ny;
        }
      }
    }
  }

  function applyFriction(ball, dt) {
    const speed = Math.hypot(ball.vx, ball.vy);
    if (speed === 0) return;

    const newSpeed = Math.max(0, speed - FRICTION * dt);
    if (newSpeed === 0) {
      ball.vx = 0;
      ball.vy = 0;
    } else {
      const scale = newSpeed / speed;
      ball.vx *= scale;
      ball.vy *= scale;
    }
  }

  function physicsSubstep(dt) {
    for (const ball of balls) {
      if (ball.potted) continue;
      ball.x += ball.vx * dt;
      ball.y += ball.vy * dt;
    }

    for (const ball of balls) {
      if (!ball.potted && isInPocket(ball)) potBall(ball);
    }

    for (const ball of balls) {
      if (!ball.potted) handleCushions(ball);
    }

    // Several deterministic passes improve simultaneous rack collisions.
    for (let pass = 0; pass < 3; pass++) {
      resolveBallCollisions();
    }

    for (const ball of balls) {
      if (ball.potted) continue;

      if (isInPocket(ball)) {
        potBall(ball);
        continue;
      }

      handleCushions(ball);
      applyFriction(ball, dt);
    }
  }

  function advance(dt) {
    dt = finiteNumber(dt);
    if (dt <= 0) return;

    let remaining = dt;
    while (remaining > 1e-12) {
      let maxSpeed = 0;
      for (const ball of balls) {
        if (!ball.potted) {
          maxSpeed = Math.max(maxSpeed, Math.hypot(ball.vx, ball.vy));
        }
      }

      const motionLimited = maxSpeed > 0 ? (R * 0.25) / maxSpeed : Infinity;
      const h = Math.min(remaining, 1 / 240, motionLimited);
      physicsSubstep(h);
      remaining -= h;
    }
  }

  function step(dt) {
    advance(dt);
    draw();
  }

  function pause() {
    running = false;
    if (animationId) cancelAnimationFrame(animationId);
    animationId = 0;
    lastTime = 0;
  }

  function resume() {
    if (running && animationId) return;
    running = true;
    lastTime = 0;
    animationId = requestAnimationFrame(frame);
  }

  function frame(time) {
    if (!running) {
      animationId = 0;
      return;
    }

    if (lastTime) {
      const dt = Math.min(0.033, Math.max(0, (time - lastTime) / 1000));
      advance(dt);
    }
    lastTime = time;
    draw();
    animationId = requestAnimationFrame(frame);
  }

  function drawTable() {
    const felt = ctx.createRadialGradient(W / 2, H / 2, 30, W / 2, H / 2, W * 0.65);
    felt.addColorStop(0, "#14936a");
    felt.addColorStop(0.62, "#087a58");
    felt.addColorStop(1, "#045a42");
    ctx.fillStyle = felt;
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    ctx.strokeStyle = "#493018";
    ctx.lineWidth = 17;
    ctx.strokeRect(5, 5, W - 10, H - 10);

    ctx.strokeStyle = "#bf7a37";
    ctx.lineWidth = 3;
    ctx.strokeRect(10, 10, W - 20, H - 20);

    ctx.strokeStyle = "#0b3f31";
    ctx.lineWidth = 5;
    ctx.strokeRect(R, R, W - R * 2, H - R * 2);
    ctx.restore();

    for (const p of pockets) {
      const g = ctx.createRadialGradient(
        p.x - 3, p.y - 3, 2,
        p.x, p.y, POCKET_RADIUS + 5
      );
      g.addColorStop(0, "#000");
      g.addColorStop(0.72, "#050505");
      g.addColorStop(1, "#482710");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(p.x, p.y, POCKET_RADIUS + 5, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.save();
    ctx.globalAlpha = 0.1;
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 1;
    for (let y = 25; y < H; y += 18) {
      ctx.beginPath();
      ctx.moveTo(20, y);
      ctx.lineTo(W - 20, y + 3);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawBall(ball, objectNumber) {
    const x = ball.x;
    const y = ball.y;

    ctx.save();
    ctx.fillStyle = "#00281d66";
    ctx.beginPath();
    ctx.ellipse(x + 3, y + 5, R * 0.95, R * 0.65, 0, 0, Math.PI * 2);
    ctx.fill();

    const gradient = ctx.createRadialGradient(
      x - R * 0.36, y - R * 0.42, R * 0.05,
      x, y, R * 1.1
    );

    if (ball.cue) {
      gradient.addColorStop(0, "#ffffff");
      gradient.addColorStop(0.65, "#f2f0dd");
      gradient.addColorStop(1, "#a9aa9d");
    } else {
      const color = ballColors[(objectNumber - 1) % ballColors.length];
      gradient.addColorStop(0, "#ffffff");
      gradient.addColorStop(0.14, color);
      gradient.addColorStop(0.72, color);
      gradient.addColorStop(1, "#181818");
    }

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(x, y, R, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = "#0008";
    ctx.lineWidth = 1;
    ctx.stroke();

    if (!ball.cue) {
      ctx.fillStyle = "#f8f4e8";
      ctx.beginPath();
      ctx.arc(x, y, R * 0.43, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#161616";
      ctx.font = `bold ${R * 0.64}px system-ui`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(objectNumber), x, y + 0.4);
    }

    ctx.restore();
  }

  function drawAim() {
    if (!aiming) return;
    const cue = cueBall();
    if (!cue) return;

    const dx = cue.x - aimPoint.x;
    const dy = cue.y - aimPoint.y;
    const length = Math.hypot(dx, dy);
    if (length < 0.01) return;

    const nx = dx / length;
    const ny = dy / length;
    const guideLength = Math.min(360, 100 + length * 1.8);
    const power = Math.min(1, length / 190);

    ctx.save();

    ctx.strokeStyle = "#ffffffdd";
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]);
    ctx.beginPath();
    ctx.moveTo(cue.x + nx * (R + 3), cue.y + ny * (R + 3));
    ctx.lineTo(cue.x + nx * guideLength, cue.y + ny * guideLength);
    ctx.stroke();

    ctx.setLineDash([]);
    ctx.strokeStyle = "#d9bd8c";
    ctx.lineWidth = 5;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(cue.x - nx * (R + 6), cue.y - ny * (R + 6));
    ctx.lineTo(aimPoint.x, aimPoint.y);
    ctx.stroke();

    const barWidth = 180;
    const barX = W / 2 - barWidth / 2;
    const barY = H - 36;
    ctx.fillStyle = "#001b16aa";
    ctx.fillRect(barX - 4, barY - 4, barWidth + 8, 16);

    const pg = ctx.createLinearGradient(barX, 0, barX + barWidth, 0);
    pg.addColorStop(0, "#67df75");
    pg.addColorStop(0.6, "#ffd54d");
    pg.addColorStop(1, "#ef4242");
    ctx.fillStyle = pg;
    ctx.fillRect(barX, barY, barWidth * power, 8);
    ctx.strokeStyle = "#fff9";
    ctx.lineWidth = 1;
    ctx.strokeRect(barX, barY, barWidth, 8);

    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    drawTable();

    let objectNumber = 0;
    for (const ball of balls) {
      if (ball.potted) continue;
      if (!ball.cue) objectNumber++;
      drawBall(ball, objectNumber);
    }

    drawAim();

    const pottedCount = balls.reduce((n, b) => n + (!b.cue && b.potted ? 1 : 0), 0);
    const cue = cueBall();
    const moving = balls.some(
      (b) => !b.potted && Math.hypot(b.vx, b.vy) > 1
    );

    if (!cue) {
      status.textContent = `Scratch! ${pottedCount} potted — reset to continue`;
    } else if (aiming) {
      const power = Math.min(100, Math.round(
        Math.hypot(cue.x - aimPoint.x, cue.y - aimPoint.y) / 1.9
      ));
      status.textContent = `Shot power: ${power}%`;
    } else if (moving) {
      status.textContent = `${pottedCount} potted — balls are moving`;
    } else {
      status.textContent = `${pottedCount} potted — drag the cue ball to shoot`;
    }
  }

  function pointerPosition(event) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * W / rect.width,
      y: (event.clientY - rect.top) * H / rect.height
    };
  }

  canvas.addEventListener("pointerdown", (event) => {
    const cue = cueBall();
    if (!cue) return;

    const moving = balls.some(
      (b) => !b.potted && Math.hypot(b.vx, b.vy) > 1
    );
    if (moving) return;

    const p = pointerPosition(event);
    if (Math.hypot(p.x - cue.x, p.y - cue.y) <= R * 1.7) {
      aiming = true;
      aimPoint = p;
      canvas.setPointerCapture(event.pointerId);
      draw();
      event.preventDefault();
    }
  });

  canvas.addEventListener("pointermove", (event) => {
    if (!aiming) return;
    aimPoint = pointerPosition(event);
    draw();
    event.preventDefault();
  });

  function releaseShot(event) {
    if (!aiming) return;

    aimPoint = pointerPosition(event);
    const cue = cueBall();
    aiming = false;

    if (cue) {
      let vx = (cue.x - aimPoint.x) * 6;
      let vy = (cue.y - aimPoint.y) * 6;
      const speed = Math.hypot(vx, vy);

      if (speed > MAX_SHOT_SPEED) {
        const scale = MAX_SHOT_SPEED / speed;
        vx *= scale;
        vy *= scale;
      }

      if (speed > 12) shoot(vx, vy);
      else draw();
    }

    event.preventDefault();
  }

  canvas.addEventListener("pointerup", releaseShot);
  canvas.addEventListener("pointercancel", () => {
    aiming = false;
    draw();
  });

  resetButton.addEventListener("click", () => {
    reset(defaultRack());
  });

  window.sim = {
    W,
    H,
    R,
    reset,
    step,
    state,
    shoot,
    pause,
    resume
  };

  reset(defaultRack());
  animationId = requestAnimationFrame(frame);
})();
</script>
</body>
</html>
